import React from "react";
import axios from "axios";

function App({ keycloak }) {

    console.log("App received keycloak:", keycloak);

    // ✅ HARD GUARD (fixes your crash)
    if (!keycloak || !keycloak.tokenParsed) {
        console.log("⏳ Waiting for Keycloak...");
        return <div>Loading authentication...</div>;
    }

    const callPrivateApi = async () => {
        try {
            await keycloak.updateToken(30);

            const response = await axios.get(
                "http://localhost:7070/api/product",
                {
                    headers: {
                        Authorization: `Bearer ${keycloak.token}`,
                    },
                }
            );

            console.log(response.data);

        } catch (error) {
            console.error("API error:", error);
        }
    };

    return (
        <div style={{ padding: "20px" }}>
            <h2>Keycloak React App</h2>

            <p>
                <strong>User:</strong>{" "}
                {keycloak.tokenParsed?.preferred_username}
            </p>

            <button onClick={callPrivateApi}>
                Call API
            </button>

            <br /><br />

            <button onClick={() => keycloak.logout()}>
                Logout
            </button>
        </div>
    );
}

export default App;

import { useMemo, useState } from "react";
import { Navigate, Route, Routes } from "react-router-dom";
import "./App.css";
import Layout from "./components/Layout";
import CreateProductPage from "./pages/CreateProductPage";
import InventoryCheckPage from "./pages/InventoryCheckPage";
import PlaceOrderPage from "./pages/PlaceOrderPage";
import ProductListPage from "./pages/ProductListPage";

function App({ keycloak }) {
  const [cartItems, setCartItems] = useState([]);

  const addToCart = (product) => {
    setCartItems((previous) => {
      const existing = previous.find((item) => item.id === product.id);
      if (existing) {
        return previous.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }

      return [
        ...previous,
        {
          id: product.id,
          name: product.name,
          price: Number(product.price),
          quantity: 1,
        },
      ];
    });
  };

  const updateCartItemQuantity = (productId, quantity) => {
    const safeQuantity = Math.max(1, Number(quantity));
    setCartItems((previous) =>
      previous.map((item) => (item.id === productId ? { ...item, quantity: safeQuantity } : item))
    );
  };

  const removeFromCart = (productId) => {
    setCartItems((previous) => previous.filter((item) => item.id !== productId));
  };

  const clearCart = () => {
    setCartItems([]);
  };

  const cartSummary = useMemo(() => {
    const totalItems = cartItems.reduce((acc, item) => acc + item.quantity, 0);
    const totalPrice = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);
    return { totalItems, totalPrice };
  }, [cartItems]);

  if (!keycloak || !keycloak.tokenParsed) {
    return <div className="loading">Loading authentication...</div>;
  }

  return (
    <Routes>
      <Route
        path="/"
        element={
          <Layout
            keycloak={keycloak}
            cartItems={cartItems}
            cartSummary={cartSummary}
            addToCart={addToCart}
            updateCartItemQuantity={updateCartItemQuantity}
            removeFromCart={removeFromCart}
            clearCart={clearCart}
          />
        }
      >
        <Route
          index
          element={<Navigate to="/shop" replace />}
        />
        <Route path="products" element={<ProductListPage />} />
        <Route path="products/create" element={<CreateProductPage />} />
        <Route path="orders/create" element={<PlaceOrderPage />} />
        <Route path="shop" element={<ProductListPage />} />
        <Route path="checkout" element={<PlaceOrderPage />} />
        <Route path="inventory/check" element={<InventoryCheckPage />} />
        <Route path="*" element={<Navigate to="/shop" replace />} />
      </Route>
    </Routes>
  );
}

export default App;

function ApiResultCard({ title, value }) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const textValue = typeof value === "string" ? value : JSON.stringify(value, null, 2);

  return (
    <section className="result-card">
      <h3>{title}</h3>
      <pre>{textValue}</pre>
    </section>
  );
}

export default ApiResultCard;

import { NavLink, Outlet } from "react-router-dom";

const navItems = [
  { to: "/shop", label: "Shop" },
  { to: "/checkout", label: "Cart & Checkout" },
  { to: "/products/create", label: "Seller: Add Product" },
  { to: "/inventory/check", label: "Inventory Lookup" },
];

function Layout({
  keycloak,
  cartItems,
  cartSummary,
  addToCart,
  updateCartItemQuantity,
  removeFromCart,
  clearCart,
}) {
  return (
    <div className="app-shell">
      <header className="app-header">
        <div className="brand-block">
          <span className="brand">SKT Mart</span>
          <p className="subtitle">Amazon-style storefront powered by your existing microservice endpoints.</p>
        </div>
        <div className="header-actions">
          <span className="user-pill">{keycloak?.tokenParsed?.preferred_username || "Authenticated user"}</span>
          <NavLink to="/checkout" className="cart-pill">
            Cart ({cartSummary.totalItems}) - ${cartSummary.totalPrice.toFixed(2)}
          </NavLink>
          <button type="button" onClick={() => keycloak.logout()}>
            Logout
          </button>
        </div>
      </header>

      <nav className="main-nav">
        {navItems.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            className={({ isActive }) => (isActive ? "nav-link active" : "nav-link")}
          >
            {item.label}
          </NavLink>
        ))}
      </nav>

      <main className="content-area">
        <Outlet
          context={{
            keycloak,
            cartItems,
            cartSummary,
            addToCart,
            updateCartItemQuantity,
            removeFromCart,
            clearCart,
          }}
        />
      </main>
    </div>
  );
}

export default Layout;

function ProductCard({ product, onAddToCart }) {
  const price = Number(product.price || 0);

  return (
    <article className="product-card">
      <div className="product-card-body">
        <p className="product-id">SKU: {product.id}</p>
        <h3>{product.name}</h3>
        <p className="product-description">{product.description}</p>
      </div>
      <div className="product-card-footer">
        <strong>${price.toFixed(2)}</strong>
        <button type="button" onClick={() => onAddToCart(product)}>
          Add to Cart
        </button>
      </div>
    </article>
  );
}

export default ProductCard;

